import { expect, expectTypeOf, assertType } from "./test/expect-shim.mjs";
import { mapKeysAsync } from "./src/object/mapKeysAsync.js";
import { delay } from "./src/promise/delay.js";
{
{
{
const obj = { a: 1, b: 2, c: 3, d: 4, e: 5, f: 6, g: 7, h: 8, i: 9, j: 10 };
        let running = 0;
        let maxRunning = 0;
        const fn = async (value, key) => {
            running++;
            if (running > maxRunning) {
                maxRunning = running;
            }
            await delay(20);
            running--;
            return key + value;
        };
        await mapKeysAsync(obj, fn);
        expect(maxRunning).toBe(10);
}
}
}
